import React, { useState } from "react";
import axios from "axios";
import "../Styles/PostJob.css";

const PostJob = () => {
  const [jobData, setJobData] = useState({
    jobTitle: "",
    category: "",
    sector: "",
    rate: "",
    rateType: "",
    skills: "",
    description: "",
    payout: "",
  });

  const CATEGORIES = [
    "Design / Marketing",
    "Technology / IT",
    "Business / Finance",
    "Education / Training",
    "Logistics / Operations",
  ];

  const SECTORS = ["Private Company", "Government", "NGO", "Freelance"];

  const RATE_TYPES = ["Per Hour", "Per Task", "Per Day"];

  const handleChange = (e) => {
    setJobData({ ...jobData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const company = JSON.parse(localStorage.getItem("loggedUser"));
      if (!company) {
        alert("Please log in first.");
        return;
      }

      await axios.post("http://localhost:3001/addJob", {
        ...jobData,
        organization: company.companyName,
      });

      alert("Job posted successfully!");
      setJobData({
        jobTitle: "",
        category: "",
        sector: "",
        rate: "",
        rateType: "",
        skills: "",
        description: "",
        payout: "",
      });
    } catch (err) {
      console.error(err);
      alert("Failed to post job.");
    }
  };

  return (
    <div className="postjob-page">
      <div className="postjob-card">
        <h1 className="page-title">
          Post a <span className="accent">Job</span>
        </h1>
        <p className="page-sub">Add a new job listing for students</p>

        <form onSubmit={handleSubmit}>
          {/* Job Title */}
          <label>Job Title</label>
          <input
            type="text"
            name="jobTitle"
            value={jobData.jobTitle}
            onChange={handleChange}
            placeholder="Graphic Designer"
          />

          {/* Category + Sector */}
          <div className="row-flex">
            {/* Category = Dropdown */}
            <div className="col-half">
              <label>Category</label>
              <select
                name="category"
                value={jobData.category}
                onChange={handleChange}
              >
                <option value="">Select category</option>
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>

            {/* Sector = Radio Buttons */}
            <div className="col-half">
              <label>Sector</label>

              {SECTORS.map((s) => (
                <div
                  key={s}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "8px",
                    marginBottom: "6px",
                  }}
                >
                  <input
                    type="radio"
                    name="sector"
                    value={s}
                    checked={jobData.sector === s}
                    onChange={handleChange}
                  />
                  <span>{s}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Rate + Rate Type */}
          <div className="row-flex">
            <div className="col-half">
              <label>Rate (OMR)</label>
              <input
                type="number"
                name="rate"
                value={jobData.rate}
                onChange={handleChange}
                placeholder="10"
              />
            </div>

            <div className="col-half">
              <label>Rate Type</label>
              <select
                name="rateType"
                value={jobData.rateType}
                onChange={handleChange}
              >
                <option value="">Select type</option>
                {RATE_TYPES.map((r) => (
                  <option key={r} value={r}>
                    {r}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Skills */}
          <label>Skills Required</label>
          <input
            type="text"
            name="skills"
            value={jobData.skills}
            onChange={handleChange}
            placeholder="Photoshop, Canva, Social Media"
          />

          {/* Description */}
          <label>Description</label>
          <textarea
            name="description"
            value={jobData.description}
            onChange={handleChange}
            placeholder="Explain job responsibilities and requirements"
          />

          {/* Payout */}
          <label>Payout (optional)</label>
          <input
            type="text"
            name="payout"
            value={jobData.payout}
            onChange={handleChange}
            placeholder="e.g. After project completion"
          />

          {/* Actions */}
          <div className="actions">
            <button type="submit" className="btn-primary">
              Post Job
            </button>

            <button
              type="button"
              className="btn-ghost"
              onClick={() =>
                setJobData({
                  jobTitle: "",
                  category: "",
                  sector: "",
                  rate: "",
                  rateType: "",
                  skills: "",
                  description: "",
                  payout: "",
                })
              }
            >
              Clear
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default PostJob;
